{"revision":4,"files":[{"path":"slugify.mjs","hash":"4d4814610f2ae32d7387f779638a244d538082e343fa9704ed8be4b0c73b1dc0","content":"/**
 * Convert a string into a URL-friendly ASCII slug.
 *
 * @param {string} value
 * @returns {string}
 */
export function slugify(value) {
  if (typeof value !== "string") {
    throw new TypeError("slugify value must be a string");
  }

  return value
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
","mode":420},{"path":"slugify.test.mjs","hash":"901dd2e7e4eec15fe8a969807d36ead8ef321fddceae6232f971f5446cba32f1","content":"import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import test from 'node:test';

import { slugify } from './slugify.mjs';

test('slugifies the documented examples', () => {
  assert.equal(slugify('Hello, World!'), 'hello-world');
  assert.equal(slugify('Café déjà vu'), 'cafe-deja-vu');
  assert.equal(slugify('  A__B  '), 'a-b');
});

test('returns an empty slug for empty or punctuation-only input', () => {
  assert.equal(slugify(''), '');
  assert.equal(slugify('!?—...'), '');
});

test('collapses repeated separators and trims their edges', () => {
  assert.equal(slugify('--one___two!!three--'), 'one-two-three');
});

test('rejects non-string values', () => {
  for (const value of [null, undefined, 42, {}, []]) {
    assert.throws(() => slugify(value), TypeError);
  }
});

test('CLI prints a slug for arguments', () => {
  const result = spawnSync(process.execPath, ['cli.mjs', 'Café', 'déjà', 'vu'], {
    encoding: 'utf8',
  });

  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'cafe-deja-vu\n');
  assert.equal(result.stderr, '');
});

test('CLI reports usage and fails without arguments', () => {
  const result = spawnSync(process.execPath, ['cli.mjs'], { encoding: 'utf8' });

  assert.equal(result.status, 1);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /usage/i);
});
